package com.trangnx.ttsbrowser.tts.edge

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Test

class EdgeTokenGeneratorTest {
    /** Independent vectors generated by upstream edge-tts drm.generate_sec_ms_gec_v2. */
    @Test fun `v2 token matches upstream vectors`() {
        assertEquals(
            "52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6",
            EdgeTokenGenerator.generate(0L),
        )
        assertEquals(
            "2CD23A2CA0B2595A-F3C846C370E05F9CC83ACC5F995C5F5D87A4D0F14CE8936A0F902E64099E38A2",
            EdgeTokenGenerator.generate(1_700_000_000_000L),
        )
        assertEquals(
            "E407D2CB684EDB46-3903E2EFD84C9CCC081272AFDEC7D4B956F42E53B3004C07FBCB145FF2B07112",
            EdgeTokenGenerator.generate(1_792_969_200_000L),
        )
    }

    @Test fun `rounds down at exact five minute boundary`() {
        val start = 1_792_969_200_000L
        assertEquals(EdgeTokenGenerator.generate(start), EdgeTokenGenerator.generate(start + 299_999))
        assertNotEquals(EdgeTokenGenerator.generate(start), EdgeTokenGenerator.generate(start + 300_000))
    }
}
